import fs from 'node:fs';import {readVerifiedArtifact} from '../../../scripts/audits/japanese_master_index_v4/artifact_rows_v1.mjs';import {contentFingerprint} from '../../../scripts/audits/japanese_master_index_v4/deterministic_artifact_v1.mjs';import assert from 'node:assert/strict';const repoRoot=process.cwd(),manifestPath='docs/audits/japanese_master_index_v4/final/jpn_master_resolved_card_identities_v1.json';const {artifact:manifest}=await readVerifiedArtifact(manifestPath,{repoRoot});const d=manifest.content.dataset,all=[];for(const [i,p] of d.shard_paths.entries()){const {artifact}=await readVerifiedArtifact(p,{repoRoot});assert.equal(artifact.content.shard_index,i+1);all.push(...artifact.content.rows)}assert.equal(contentFingerprint(all),d.content_fingerprint_sha256);const review=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/evidence-review-20261119.json')),snapshot=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/jpn-dp4-review-readback-20261119.json'));const pairs=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/species_name_pairs.json'));const parent=new Map(snapshot.parents.map(x=>[x.record.id,x.record])),master=new Map(all.filter(x=>x.existing_card_print_id).map(x=>[x.existing_card_print_id,x]));const norm=s=>s.normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g,'');const findings=[];for(const c of review.candidates){const p=parent.get(c.card_print_id),m=master.get(c.card_print_id),species=pairs.filter(x=>x.ja===p.name);if(species.length!==1)continue;const displayed=(m.collector_facing_name_en??'').split(' (')[0],match=norm(displayed)===norm(species[0].en);findings.push({gv_id:c.gv_id,japanese_name:p.name,species_english:species[0].en,species_id:species[0].species_id,master_english:m.collector_facing_name_en,master_family:m.family_key,match});}const out={generated_at:new Date().toISOString(),scope:'Heuristic comparison with retained species-name pairs; flags require individual identity review and do not prove a live catalog error.',source:'docs/audits/catalog_jpn_artist_completion_v1_20261109/species_name_pairs.json',review_candidates:review.candidate_count,exact_japanese_species_name_matches:findings.length,matching_english:findings.filter(x=>x.match).length,english_disagreements:findings.filter(x=>!x.match).length,findings};if(!process.argv.includes('--check'))fs.writeFileSync('docs/audits/jpn_dp4_artist_review_20261119/master-species-name-diagnostic-20261119.json',JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({review_candidates:out.review_candidates,exact_japanese_species_name_matches:out.exact_japanese_species_name_matches,matching_english:out.matching_english,english_disagreements:out.english_disagreements,examples:findings.filter(x=>!x.match).slice(0,5)}));
